# Searches this database's records by name or meaning.
RECORD = {
    "id": "JAH-NAMES-000001",
    "name": "How name etymology works",
    "kind": "name collection",
    "meaning": "Name etymology traces a name back through its root words: the earliest recorded form, the language family it belongs to,"
}
